import React from "react";

export default function Certificate(opt) {
  const { description, img, date } = opt;
  return (
    <article class="certificate-item">
      <a href="assets/doc_react.pdf" target="_blank">
        <img src="assets/react.jpg" alt="Сертификат React. Разработка сложных клиентских приложений" />
        <p class="certificate-desc">React. Разработка сложных клиентских приложений.</p>
        <p class="certificate-date">27 сентября — 28 ноября 2021</p>
      </a>
    </article>
  );
}
